api.controller = function($scope, spUtil) {
    $scope.navigateTo = function(page) {
        spUtil.navigateTo(page);
    };
};

sp_widget.css:
.nav-menu {
  background-color: #004080;
  padding: 10px;
  border-radius: 5px;
  display: flex;
  justify-content: center;
}

.nav-menu ul {
  list-style: none;
  display: flex;
  gap: 20px;
  padding: 0;
}

.nav-menu ul li {
  display: inline;
}

.nav-menu ul li a {
  color: white;
  text-decoration: none;
  font-size: 16px;
  padding: 10px 15px;
  border-radius: 5px;
}

.nav-menu ul li a:hover {
  background-color: #ffcc00;
  color: #004080;
}
.nav-menu {
  width: 100%;
}
.nav-menu {
  min-height: 50px;
}
